// Reload refetches the object from the database
// using the primary keys with an executor.
func (o *Cest) Reload(ctx context.Context, exec boil.ContextExecutor) error {
	ret, err := FindCest(ctx, exec, o.CestNumero)
	if err != nil {
		return err
	}

	*o = *ret
	return nil
}

// ReloadAll refetches every row with matching primary key column values
// and overwrites the original object slice with the newly updated slice.
func (o *CestSlice) ReloadAll(ctx context.Context, exec boil.ContextExecutor) error {
	if o == nil || len(*o) == 0 {
		return nil
	}

	slice := CestSlice{}
	var args []interface{}
	for _, obj := range *o {
		pkeyArgs := queries.ValuesFromMapping(reflect.Indirect(reflect.ValueOf(obj)), cestPrimaryKeyMapping)
		args = append(args, pkeyArgs...)
	}

	sql := "SELECT `cest`.* FROM `cest` WHERE " +
		strmangle.WhereClauseRepeated(string(dialect.LQ), string(dialect.RQ), 0, cestPrimaryKeyColumns, len(*o))

	q := queries.Raw(sql, args...)

	err := q.Bind(ctx, exec, &slice)
	if err != nil {
		return errors.Wrap(err, "models: unable to reload all in CestSlice")
	}

	*o = slice

	return nil
}

// CestExists checks if the Cest row exists.
func CestExists(ctx context.Context, exec boil.ContextExecutor, cestNumero int) (bool, error) {
	var exists bool
	sql := "select exists(select 1 from `cest` where `cest_numero`=? limit 1)"

	if boil.IsDebug(ctx) {
		writer := boil.DebugWriterFrom(ctx)
		fmt.Fprintln(writer, sql)
		fmt.Fprintln(writer, cestNumero)
	}
	row := exec.QueryRowContext(ctx, sql, cestNumero)

	err := row.Scan(&exists)
	if err != nil {
		return false, errors.Wrap(err, "models: unable to check if cest exists")
	}

	return exists, nil
}

// Exists checks if the Cest row exists.
func (o *Cest) Exists(ctx context.Context, exec boil.ContextExecutor) (bool, error) {
	return CestExists(ctx, exec, o.CestNumero)
}
